import type {ReactNode, Ref} from 'react';
import React, {Fragment, forwardRef, useCallback, useEffect, useMemo, useRef} from 'react';

import {ChevronDown, ChevronRight} from '@gravity-ui/icons';
import type {
    ButtonButtonProps,
    SelectProps as CommonSelectProps,
    SelectOption,
} from '@gravity-ui/uikit';
import {
    ActionTooltip,
    Button,
    Select as CommonSelect,
    Icon,
    Loader,
    Text,
    TextInput,
    getConfig,
} from '@gravity-ui/uikit';

import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import {cnSelect} from './Select.classname';
import {defaultMessages} from './i18n';
import {filterOption} from './utils/filterOption';
import {getValueOption} from './utils/getValueOption';
import {isGroupOption} from './utils/isGroupOption';
import {renderOption} from './utils/renderOption';

import './Select.scss';

export type MultiSelectProps = CommonSelectProps & {
    id?: string;
    loading?: boolean;
    loadingItems?: boolean;
    controlProps?: ButtonButtonProps;
    withArrow?: boolean;
    title?: string;
    icon?: ReactNode;
    selectSize?: CommonSelectProps['size'];
    renderDisplayValue?: (value: SelectOption[]) => ReactNode;
    chevronView?: 'desktop' | 'touch';
    autoFocus?: boolean;
    withSpecialNoOptions?: boolean;
    disablePortal?: boolean;
    disableTooltip?: boolean;
    filterOption?: (option: SelectOption, filter: string) => boolean;
};

export const MultiSelect: React.ForwardRefExoticComponent<
    MultiSelectProps & React.RefAttributes<HTMLButtonElement>
> = forwardRef<HTMLButtonElement, MultiSelectProps>(
    (
        {
            id,
            loading,
            loadingItems,
            disabled,
            renderControl: providedRenderControl,
            className,
            options,
            value,
            width,
            size,
            name,
            placeholder,
            popupClassName,
            renderOption: providedRenderOption = renderOption,
            renderSelectedOption,
            renderDisplayValue,
            controlProps,
            controlClassName,
            withArrow = true,
            title,
            icon,
            validationState,
            selectSize,
            chevronView = 'desktop',
            open,
            filterable,
            disablePortal,
            filterOption: providedFilterOption,
            renderFilter: providedRenderFilter,
            autoFocus,
            filterPlaceholder,
            withSpecialNoOptions,
            onOpenChange,
            disableTooltip,
            ...props
        },
        ref,
    ) => {
        const config = getConfig();
        const {t} = useLocalizedString(defaultMessages, config.lang);

        const inputRef = useRef<HTMLInputElement | null>(null);

        const renderControl = useCallback<NonNullable<CommonSelectProps['renderControl']>>(
            (renderControlProps, config) => {
                const {triggerProps, ref, open} = renderControlProps;
                const hasError = validationState === 'invalid';

                if (loading) {
                    return (
                        <div
                            ref={ref as Ref<HTMLDivElement>}
                            className={cnSelect('button-wrapper')}
                        >
                            <ActionTooltip
                                title={title ?? ''}
                                disabled={disableTooltip || !title}
                                placement="bottom"
                            >
                                <Button
                                    view="outlined"
                                    size={size}
                                    disabled
                                    width="max"
                                    name={name}
                                    className={cnSelect(
                                        'button',
                                        {
                                            loading: true,
                                            error: hasError,
                                            platform: 'desktop',
                                        },
                                        controlClassName,
                                    )}
                                    {...controlProps}
                                    id={id}
                                >
                                    <Loader className={cnSelect('loader')} />
                                    {withArrow && (
                                        <Icon
                                            data={
                                                chevronView === 'touch' ? ChevronRight : ChevronDown
                                            }
                                        />
                                    )}
                                </Button>
                            </ActionTooltip>
                        </div>
                    );
                }

                if (providedRenderControl) {
                    return providedRenderControl(renderControlProps, config);
                }

                const valueOptions: SelectOption[] = [];

                if (value && value.length) {
                    for (const valueItem of value) {
                        const valueOption = getValueOption(options ?? [], valueItem);

                        if (valueOption) {
                            valueOptions.push(valueOption);
                        }
                    }
                }

                return (
                    <div ref={ref as Ref<HTMLDivElement>} className={cnSelect('button-wrapper')}>
                        <ActionTooltip
                            title={title ?? ''}
                            disabled={disableTooltip || !title}
                            placement="bottom"
                        >
                            <Button
                                view="outlined"
                                size={size}
                                {...triggerProps}
                                name={name}
                                aria-haspopup="listbox"
                                width="max"
                                disabled={disabled}
                                className={cnSelect(
                                    'button',
                                    {
                                        empty: valueOptions.length === 0,
                                        'with-icon': Boolean(icon),
                                        error: hasError,
                                        platform: 'desktop',
                                    },
                                    controlClassName,
                                )}
                                {...controlProps}
                                id={id}
                            >
                                {icon}
                                {renderDisplayValue ? (
                                    renderDisplayValue(valueOptions)
                                ) : (
                                    <>
                                        {valueOptions.length === 0 && (placeholder || '—')}
                                        {valueOptions.map((item, index) => (
                                            <Fragment key={item.value}>
                                                {renderSelectedOption
                                                    ? renderSelectedOption(item, index)
                                                    : item.text || item.content}
                                                {index < valueOptions.length - 1 && ', '}
                                            </Fragment>
                                        ))}
                                    </>
                                )}
                                {withArrow && (
                                    <Icon
                                        size={chevronView === 'touch' ? 24 : 16}
                                        data={chevronView === 'touch' ? ChevronRight : ChevronDown}
                                        className={cnSelect('chevron', {
                                            open,
                                        })}
                                    />
                                )}
                            </Button>
                        </ActionTooltip>
                    </div>
                );
            },
            [
                validationState,
                loading,
                providedRenderControl,
                value,
                title,
                disableTooltip,
                id,
                size,
                name,
                disabled,
                icon,
                controlClassName,
                controlProps,
                renderDisplayValue,
                placeholder,
                withArrow,
                chevronView,
                options,
                renderSelectedOption,
            ],
        );

        const renderPopup = useCallback<NonNullable<CommonSelectProps['renderPopup']>>(
            ({renderFilter, renderList}) => (
                <>
                    {renderFilter()}
                    {renderList()}
                </>
            ),
            [],
        );

        const renderFilter = useCallback<NonNullable<CommonSelectProps['renderFilter']>>(
            ({inputProps}) => {
                const hasDefaultValue = (props.defaultValue?.length ?? 0) > 0;

                const controlProps = {
                    role: 'combobox',
                    'aria-activedescendant': inputProps['aria-activedescendant'],
                    'aria-controls': inputProps['aria-controls'],
                    'aria-label': inputProps['aria-label'],
                };

                return (
                    <TextInput
                        autoFocus={autoFocus && !hasDefaultValue}
                        className={cnSelect('filter')}
                        {...inputProps}
                        controlProps={controlProps}
                        controlRef={inputRef}
                        size={selectSize}
                        name={name}
                    />
                );
            },
            [autoFocus, props.defaultValue, selectSize, name],
        );

        const optionsWithLoading = useMemo(() => {
            if (!loadingItems) {
                if (!options?.length) {
                    return [
                        {
                            value: '',
                            disabled: true,
                            content: withSpecialNoOptions ? (
                                <div className={cnSelect('no-options')}>
                                    <Text color="primary" variant="subheader-3">
                                        {t('no-options-title')}
                                    </Text>
                                    <Text variant="body-2">{t('no-options-description')}</Text>
                                </div>
                            ) : (
                                <div className={cnSelect('no-options')}>{t('no-options')}</div>
                            ),
                        },
                    ];
                }

                return options;
            }

            return [
                {
                    value: '',
                    disabled: true,
                    content: (
                        <div className={cnSelect('items-loader')}>
                            <Loader size="m" />
                        </div>
                    ),
                },
            ];
        }, [loadingItems, options, t, withSpecialNoOptions]);

        const withGroups = options?.some(isGroupOption);

        useEffect(() => {
            let timer: NodeJS.Timeout | undefined;

            if (open && inputRef.current) {
                timer = setTimeout(() => inputRef.current?.focus({preventScroll: true}), 0);
            }

            return () => {
                if (timer) {
                    clearTimeout(timer);
                }
            };
            // eslint-disable-next-line react-hooks/exhaustive-deps -- inputRef.current must be in list
        }, [open && inputRef.current]);

        return (
            <CommonSelect
                disablePortal={disablePortal}
                disabled={disabled || loading}
                options={optionsWithLoading}
                value={value}
                renderControl={renderControl}
                multiple
                renderOption={
                    loadingItems || !options?.length ? renderOption : providedRenderOption
                }
                ref={ref}
                filterPlaceholder={filterPlaceholder ?? t('search')}
                popupClassName={cnSelect(
                    'popup',
                    {
                        'with-groups': withGroups,
                        filterable,
                    },
                    popupClassName,
                )}
                filterOption={providedFilterOption ?? filterOption}
                width={width}
                className={cnSelect(null, className)}
                size={size}
                validationState={validationState}
                renderPopup={renderPopup}
                open={open}
                renderFilter={providedRenderFilter ?? renderFilter}
                filterable={filterable}
                onOpenChange={onOpenChange}
                {...props}
            />
        );
    },
);

MultiSelect.displayName = 'MultiSelect';
